def _order(step='10-A1', cards=('イッテツーン', 'イッテツーン')):
    return {
        'step': step,
        'source': 'アルマムーン',
        'target': 'ロミオ',
        'general': 'ローズマリー',
        'cards': list(cards),
        'note': 'test',
    }


def _inventory(rows, selected_y=55, remaining=3):
    return {
        'rows': [{'y': 55 + 16 * i, 'card': c, 'stock': n} for i, (c, n) in enumerate(rows)],
        'selected_y': selected_y,
        'remaining': remaining,
        'inventory_evidence': 'measured_four_row_card_select',
        'observed_rows': len(rows),
    }


def test_deploy_cards_keeps_rare_card_when_live_card_stock_is_positive():
    order = _order()
    mem = {
        'chapter': 10,
        'tick': 750518,
        'card_stock': {'キャトルミュー': 37, 'イッテツーン': 9},
        'card_zero_at_start': {'step': order['step'], 'cards': ['キャトルミュー', 'エンジェリン']},
        'rare_card_kit': {order['step']: ['キャトルミュー', 'イッテツーン', 'イッテツーン']},
    }
    assert _deploy_cards(order, mem) == ['キャトルミュー', 'イッテツーン', 'イッテツーン']


def test_deploy_cards_still_skips_cards_with_zero_stock_in_card_zero_at_start():
    order = _order(cards=('エンジェリン', 'イッテツーン'))
    mem = {
        'chapter': 4,
        'tick': 1000,
        'card_stock': {'エンジェリン': 0, 'イッテツーン': 5},
        'card_zero_at_start': {'step': order['step'], 'cards': ['エンジェリン']},
    }
    assert _deploy_cards(order, mem) == ['イッテツーン']


def test_observe_card_stock_evicts_live_positive_card_from_card_zero_at_start():
    mem = {
        'card_stock': {'キャトルミュー': 0, 'エンジェリン': 0},
        'card_zero_at_start': {'step': '10-A1', 'cards': ['キャトルミュー', 'エンジェリン']},
    }
    inv = _inventory([('キャトルミュー', 37), ('イッテツーン', 9)])
    assert _observe_card_stock(mem, inv) is True
    assert mem['card_stock']['キャトルミュー'] == 37
    assert mem['card_zero_at_start']['cards'] == ['エンジェリン']


